package com.travelmate.model;

/**
 * Actionable travel recommendation generated by the weather heuristics engine.
 */
public class RecommendationItem {
    public String title;
    public String description;
    public String category; // "Safety", "Clothing", "Timing", "Alternative"
    public String severity; // "INFO", "WARNING", "CRITICAL"
    public String icon;

    public RecommendationItem() {
    }

    public RecommendationItem(String title, String description, String category, String severity, String icon) {
        this.title = title;
        this.description = description;
        this.category = category;
        this.severity = severity;
        this.icon = icon;
    }
}

